<?php
$q=trim((string)($_GET['q']??''));
$teachers=rows('SELECT t.*, u.username, COALESCE(st.class_count,0) AS class_count, COALESCE(st.period_count,0) AS period_count FROM teachers t LEFT JOIN users u ON u.teacher_id=t.id LEFT JOIN (SELECT teacher_id, COUNT(*) AS class_count, SUM(period_end-period_start+1) AS period_count FROM schedules GROUP BY teacher_id) st ON st.teacher_id=t.id ORDER BY t.full_name');
if($q!=='') $teachers=array_values(array_filter($teachers,static fn(array $t):bool=>stripos($t['full_name'].' '.$t['email'].' '.$t['expertise'],$q)!==false));
?>
<div class="page-heading heading-with-action"><div><div class="eyebrow">DANH MỤC HỆ THỐNG</div><h1>Đội ngũ giảng viên <span class="heading-dot">.</span></h1><p>Quản lý hồ sơ, chuyên môn và tài khoản truy cập của giảng viên.</p></div><a class="btn btn-primary" href="<?= e(app_url('teacher-form')) ?>"><svg><use href="#i-plus"/></svg> Thêm giảng viên</a></div>
<section class="panel"><form class="search-filters" method="get"><input type="hidden" name="page" value="teachers"><div class="search-box"><svg><use href="#i-search"/></svg><input name="q" value="<?= e($q) ?>" placeholder="Tìm theo tên, email, chuyên môn..."></div><button class="btn btn-dark btn-sm">Tìm kiếm</button><a class="btn btn-ghost btn-sm" href="<?= e(app_url('teachers')) ?>">Đặt lại</a></form><div class="table-topline"><strong><?= count($teachers) ?> giảng viên</strong><span>Mỗi giảng viên có tài khoản truy cập riêng</span></div><div class="table-scroll"><table class="data-table"><thead><tr><th>GIẢNG VIÊN</th><th>CHUYÊN MÔN</th><th>TÀI KHOẢN</th><th>LỊCH DẠY / TUẦN</th><th>LIÊN HỆ</th><th class="actions-col">THAO TÁC</th></tr></thead><tbody><?php foreach($teachers as $teacher): ?><tr><td><span class="teacher-identity"><span class="avatar-inline avatar-big"><?= e(initials($teacher['full_name'])) ?></span><span><strong><?= e($teacher['full_name']) ?></strong><small><?= e($teacher['email']) ?></small></span></span></td><td><span class="expertise-label"><?= e($teacher['expertise']) ?></span></td><td><code class="username-code"><?= e($teacher['username']??'Chưa cấp') ?></code></td><td><strong><?= (int)$teacher['class_count'] ?> buổi</strong><small class="subtle"><?= (int)$teacher['period_count'] ?> tiết</small></td><td><?= e($teacher['phone']?:'—') ?></td><td><div class="row-actions"><a class="action-edit" href="<?= e(app_url('teacher-form',['id'=>$teacher['id']])) ?>">Sửa</a><form method="post" action="<?= e(app_url('teachers')) ?>" data-confirm="Xóa giảng viên <?= e($teacher['full_name']) ?>? Chỉ có thể xóa khi không còn lịch dạy."><?= csrf_field() ?><input type="hidden" name="action" value="delete-teacher"><input type="hidden" name="id" value="<?= (int)$teacher['id'] ?>"><button class="action-delete">Xóa</button></form></div></td></tr><?php endforeach; ?><?php if(!$teachers): ?><tr><td colspan="6" class="table-empty">Chưa có giảng viên phù hợp.</td></tr><?php endif; ?></tbody></table></div></section>
